-- Zul'Gurub (map 859) and Zul'Aman (map 568): spawn differences against the LoA world DB, whose scripts these
-- dungeons run.

-- ==========================================================================
-- Zul'Gurub: static spawns of creatures the scripts summon themselves
-- ==========================================================================
-- boss_kilnara summons its 16 Prides of Bethekk (52061) and the Cave In Stalkers (52387), boss_jindo_the_godbreaker
-- the Spirit of Hakkar (52222) and Hakkar's Chains (52430). With the static spawns as well, each was there twice.
-- (Zanzil's static Berserkers and Zombies stay: they are the inert corpses in his graveyard.)
DELETE FROM `creature_addon` WHERE `guid` IN (SELECT `guid` FROM `creature` WHERE `map` = 859 AND `id` IN (52061, 52387, 52222, 52430, 52150, 52650));
DELETE FROM `creature` WHERE `map` = 859 AND `id` IN (52061, 52387, 52222, 52430);
-- A second Jin'do (52150) and a Shadow of Hakkar (52650) stood in the arena for everyone to see. They are the spirit
-- world copies; the script uses the boss himself and the summoned Spirit of Hakkar there.
DELETE FROM `creature` WHERE `map` = 859 AND `id` IN (52150, 52650);

-- ==========================================================================
-- Zul'Gurub: Jin'do's spirit world is phase 173 (Spirit World, spell 96689)
-- ==========================================================================
-- LoA keeps these in phase mask 2. SkyFire shows creatures by phase id, and they had none, so the Twisted Spirits,
-- Gurubashi Spirits, Spirit Portals and Gurubashi Shadows stood in the normal world.
UPDATE `creature` SET `phaseId` = 173, `phaseGroup` = 0 WHERE `map` = 859 AND `id` IN (52624, 52730, 52532, 52732);

-- ==========================================================================
-- Zul'Gurub: spawns LoA has and SkyFire lacked
-- ==========================================================================
-- Same entry, no SkyFire spawn of that entry left to pair it with, and no SkyFire creature of any entry within 4 yards.
-- Waypoint paths and per-spawn addons come along. GUIDs 9507000+.
DELETE FROM `creature` WHERE `guid` BETWEEN 9507000 AND 9507107;

DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9507000 AND 9507107;

DELETE FROM `waypoint_data` WHERE `id` BETWEEN 95070000 AND 95071070;

-- ==========================================================================
-- Zul'Aman: spawns LoA has and SkyFire lacked (same rule). GUIDs 9507500+.
-- ==========================================================================
DELETE FROM `creature` WHERE `guid` BETWEEN 9507500 AND 9507602;

DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9507500 AND 9507602;

DELETE FROM `waypoint_data` WHERE `id` BETWEEN 95075000 AND 95076020;
